from pathlib import Path
import re
p=Path(__file__).parent
old=(p/'source/reader-template.html').read_text()
def part(cond):
    start=old.index('<template x-if="'+cond+'">');depth=0
    for m in re.finditer(r'</?template\b',old[start:]):
        depth+= -1 if m.group().startswith('</') else 1
        if depth==0:return old[start:start+m.end()+1]
reader=part("screen==='reader'")
reader=reader.replace("'图包 '+(selected+1)+' / '+packs.filter(p=>!trashIds.includes(p.id)).length", "'本次范围 · '+(queueAt+1)+' / '+queueIds.length")
reader=reader.replace('<button @click="movePack(1,true)">下一包', '<button @click="movePack(1)" x-show="nextPack">下一包')
reader=reader.replace('<button class="primary" @click="movePack(1,true)">阅读下一包</button>', '<button class="primary" x-show="nextPack" @click="movePack(1)">阅读下一包</button>')
reader=reader.replace('返回上一页','返回来源')
reader=reader.replace('<span x-text="\'本次范围 · \'+(queueAt+1)+\' / \'+queueIds.length"></span>', '<button class="reader-scope" aria-label="查看本次图包范围" @click="panel=\'packScope\'"><span x-text="queueLabel"></span><strong x-text="(queueAt+1)+\' / \'+queueIds.length"></strong></button>')
reader=reader.replace(':class="{immersive:!controls}"', ':class="{immersive:!controls&&!packQuick, \'pack-quick\':packQuick}"')
reader=reader.replace('pack.author+\' · \'+pack.number', "(packQuick?'快速整理 · ':'')+pack.author+' · '+pack.number")
reader=reader.replace('<button class="icon" aria-label="阅读设置"', '<button class="text-button quick-done" x-show="packQuick" @click="packQuick=false">完成</button><button class="icon" x-show="!packQuick" aria-label="阅读设置"')
reader=reader.replace('<div class="reader-tools">', '<div class="reader-tools" x-show="!packQuick">')
reader=reader.replace('<div class="reading-context">', '''<div class="pack-cleanup" x-show="packQuick" aria-label="图包快速整理"><button class="secondary" @click="editTags(pack.id)">整包标签</button><button class="primary danger-bg" @click="removePackNow()" aria-label="移除当前整包">移入回收站</button></div><div class="reading-context"><button class="pack-previous" x-show="packQuick" :disabled="queueAt===0" @click="movePack(-1)" aria-label="上一个图包"><span x-html="icon('back')"></span>上一包</button>''')
reader=reader.replace('x-show="!controls"', 'x-show="!controls&&!packQuick"')
settings=(p/'settings.html').read_text()
shared=[]
for name in ['reader-settings','overview','details']:
    s=part("panel==='"+name+"'")
    s=s.replace('保存标签、图包阅读进度、回收站状态和阅读偏好。','分别保存视频标签与图包标签，以及阅读进度、回收站状态和偏好。')
    shared.append(s)
